        "titolo_orig": "Caretta caretta, una strage in un mare di gas",
        "testo_it": "Strage di tartarughe Caretta caretta nell'Adriatico: sospetti sui rigassificatori di Ravenna.",
        "priorita": "Bassa",
        "id_gruppo": 31,
        "link": "https://ilmanifesto.it/caretta-caretta-una-strage-in-un-mare-di-gas",
